const CSS_EWA = `
.ewa-raiz{height:100%;overflow:auto;background:#fff}
.ewa-pad{padding:9px}
.ewa-amp{display:flex;flex-direction:column;height:100%;margin-bottom:0}
.ewa-amp.on{position:fixed;inset:7.5vh 5vw;z-index:30000;height:auto;box-shadow:0 0 0 100vmax rgba(20,35,40,.45)}
.ewa-amp-b{flex:1;min-height:0;overflow:auto}
.ewa-multi{position:relative;min-width:0;flex:1}
.ewa-multi > strong{font-size:12px;color:var(--azul)}
.ewa-multi > button{width:100%;margin-top:4px;padding:7px 9px;border:1px solid var(--linha);border-radius:6px;background:#fff;display:flex;justify-content:space-between;align-items:center;gap:6px;color:var(--texto);text-align:left}
.ewa-multi > button span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ewa-multi > button.tem{border-color:var(--verde);box-shadow:inset 3px 0 0 var(--verde)}
.ewa-multi-pop{position:fixed;z-index:2147483000;background:#fff;border:1px solid var(--linha);border-radius:8px;box-shadow:0 10px 28px rgba(0,0,0,.22);padding:9px}
.ewa-multi-pop input[type=text],.ewa-multi-pop input:not([type]){width:100%;padding:7px 9px;border:1px solid var(--linha);border-radius:6px;font:inherit}
.ewa-multi-pop .acoes{display:flex;justify-content:space-between;margin:7px 0}
.ewa-multi-pop .acoes button{border:0;background:none;color:var(--destaque);font-weight:600;font-size:12px;padding:2px}
.ewa-multi-pop .lista{overflow-y:auto}
.ewa-multi-pop label{display:flex;align-items:center;gap:7px;padding:5px 3px;cursor:pointer;font-size:12px;border-radius:4px}
.ewa-multi-pop label:hover{background:var(--palido)}
.ewa-filtros{display:flex;align-items:center;gap:10px;padding:7px 12px;background:#f5f7f5;height:100%;overflow:visible;position:relative;z-index:100}
.ewa-filtros.compacto{flex-direction:column;align-items:stretch;height:auto}
.ewa-filtros .sis{min-width:96px;text-align:center}
.ewa-filtros .sis strong{font-size:12px;color:var(--azul)}
.ewa-filtros .sis div{margin-top:4px;background:var(--azul);color:#fff;border-radius:6px;padding:7px}
.ewa-filtros .limpar{align-self:flex-end}
.ewa-recolher{width:100%;padding:5px 8px;border:0;background:var(--verde);color:#fff;font-weight:600}
.ewa-abas{display:flex;border-bottom:1px solid var(--linha)}
.ewa-abas button{flex:1;border:0;border-right:1px solid var(--linha);background:#fff;color:var(--azul);padding:9px 2px;display:grid;justify-items:center;gap:3px;font-weight:700;font-size:11px}
.ewa-abas button.on{background:var(--verde);color:#fff}
.ewa-abas.mini button{display:inline-flex;flex:none;border:0;border-radius:4px;padding:5px 8px;background:#edf2ef;margin:0 3px 6px 0;font-weight:600}
.ewa-abas.mini{border:0;flex-wrap:wrap}
.ewa-abas.mini button.on{background:var(--verde);color:#fff}
.ewa-camada{display:grid;grid-template-columns:16px 19px minmax(0,1fr) auto;align-items:center;gap:6px;padding:3px 0;cursor:pointer}
.ewa-camada .ic{color:var(--destaque)}
.ewa-camada .n{color:var(--neutro);font-size:11px;font-variant-numeric:tabular-nums}
.ewa-grade-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px}
.ewa-grade-2{display:grid;grid-template-columns:1fr 1fr;gap:4px 8px}
.ewa-inferior{display:grid;gap:7px;padding:7px;background:#f6f8f6;height:100%;overflow:auto}
.ewa-attr{display:grid;grid-template-columns:46% 54%;gap:6px;padding:5px 7px;font-size:12px}
.ewa-attr:nth-child(even){background:#f4f7f8}
.ewa-attr strong{overflow-wrap:anywhere}
.ewa-etapa{display:grid;grid-template-columns:10px minmax(0,1fr) auto;gap:7px;align-items:center;padding:5px 0;border-bottom:1px solid var(--linha);font-size:12px}
.ewa-etapa:last-child{border-bottom:0}
.ewa-etapa i{width:10px;height:10px;border-radius:3px}
.ewa-etapa small{display:block;color:var(--mudo);font-size:10.5px}
.ewa-acoes{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}
.ewa-funil > div{margin:3px auto;padding:5px 7px;color:#fff;display:flex;justify-content:space-between;gap:4px;font-size:11px;border-radius:3px}
.ewa-mobile{display:flex;align-items:stretch;gap:4px;padding:4px;background:#f5f7f5;height:100%}
.ewa-mobile > button{flex:1;min-width:0;border:1px solid var(--linha);border-radius:6px;background:#fff;color:var(--azul);font-weight:700;font-size:12px;display:flex;align-items:center;justify-content:center;gap:5px}
.ewa-dialogo{position:fixed;inset:0;z-index:20000;background:#f5f7f5;display:flex;flex-direction:column}
.ewa-dialogo > header{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;background:var(--verde);color:#fff;font-weight:700}
.ewa-dialogo > header button{background:transparent;color:#fff;border:1px solid #fff;border-radius:4px;padding:5px 9px}
.ewa-dialogo > div{flex:1;min-height:0;overflow:auto}
.ewa-pop-html{max-width:100%;overflow-wrap:anywhere;font-size:12px}
.ewa-pop-html table{width:100%;border-collapse:collapse}
.ewa-pop-html td,.ewa-pop-html th{padding:4px 6px;border-bottom:1px solid var(--linha);text-align:left}
`;


